<memory-policy>
Follow this memory policy (preset medium) whenever you read or write memory.
The requester acts as person:operator at the person level and belongs to: person:operator, team:operations.
Use only memory the policy lets the requester read, and write only what it lets them write.
Units: ttl is in seconds (null means no limit); confidence_floor and an item's confidence are between 0 and 1; budget is a number of active items per scope and class (null means no limit); lints.enabled lists the lints a lint-running condition uses and does not turn lints on.

{{
  "id": "preset.medium",
  "lints": {{
    "enabled": [
      "expired-validity",
      "source-changed",
      "scope-class-mismatch",
      "missing-provenance",
      "orphan",
      "duplicate"
    ],
    "thresholds": {{
      "near-duplicate": 0.85,
      "replay-drift.min-trials": 10,
      "replay-drift.success-floor": 0.7
    }}
  }},
  "promotion": {{
    "episodic_to_semantic": {{
      "confirmations": 3,
      "or_review": true
    }},
    "procedural": {{
      "replay_k": 4,
      "replay_n": 5
    }}
  }},
  "read": {{
    "honour_grants": true,
    "matrix": [
      {{
        "may_read": [
          "person",
          "role",
          "team",
          "org"
        ],
        "reader": "person"
      }},
      {{
        "may_read": [
          "person",
          "role",
          "team",
          "org"
        ],
        "reader": "role"
      }},
      {{
        "may_read": [
          "role",
          "team",
          "org"
        ],
        "reader": "team"
      }},
      {{
        "may_read": [
          "team",
          "org"
        ],
        "reader": "org"
      }}
    ]
  }},
  "retention": [
    {{
      "budget": 5000,
      "class": "episodic",
      "eviction": "recency",
      "scope": "person",
      "ttl": 7776000
    }},
    {{
      "budget": 2000,
      "class": "semantic",
      "eviction": "utility",
      "scope": "person",
      "ttl": null
    }},
    {{
      "budget": 200,
