      "scope": "role",
      "ttl": null
    }},
    {{
      "budget": 10000,
      "class": "semantic",
      "eviction": "utility",
      "scope": "team",
      "ttl": null
    }},
    {{
      "budget": 500,
      "class": "procedural",
      "eviction": "utility",
      "scope": "team",
      "ttl": null
    }},
    {{
