      "eviction": "manual",
      "scope": "org",
      "ttl": null
    }}
  ],
  "schema_version": 0,
  "version": 1,
  "write": [
    {{
      "allowed_sources": [
        "user",
        "document",
        "tool",
        "import",
        "model",
        "compaction"
      ],
      "confidence_floor": 0.3,
      "forbidden_classes": [],
      "requires_review": false,
      "scope": "person"
    }},
    {{
      "allowed_sources": [
        "user",
        "document",
        "tool",
        "import"
      ],
      "confidence_floor": 0.5,
      "forbidden_classes": [
        "episodic"
      ],
      "requires_review": false,
      "scope": "role"
    }},
    {{
